fn largest_divisor(n: i8) -> i8 {
    debug_assert!(n > 1);

    // For n > 1, the largest proper divisor is n / p where p is the smallest
    // divisor of n greater than 1. If n is prime, that smallest divisor is n,
    // and the result becomes 1.
    let nn = n as i16;

    // Search for the smallest divisor in [2, sqrt(n)].
    // If found, return n / that divisor (which will be the largest proper divisor).
    let mut d: i16 = 2;
    while d * d <= nn {
        if nn % d == 0 {
            return (nn / d) as i8;
        }
        d += 1;
    }

    // n is prime
    1
}